def anti_shuffle(s):
    words = s.split(' ')
    result_words = []
    for w in words:
        if w.isalpha():
            # only letters, sort
            result_words.append(''.join(sorted(w)))
        elif w and all(not c.isalnum() for c in w):
            # only punctuation, leave as is
            result_words.append(w)
        else:
            # mixed word with punctuation attached, sort all chars by ASCII
            result_words.append(''.join(sorted(w)))
    return ' '.join(result_words)

